n = int(input())
white = []
g = [[] for _ in range(n)]
d = [0] * n
for i in range(n - 1):
	(x, y, t) = list(map(int, input().strip().split()))
	x -= 1
	y -= 1
	if x >= 0 and y >= 0 and (x < n) and (y < n):
		g[x].append(y)
		g[y].append(x)
	if t == 2:
		white.append((x, y))
(stack, parent) = ([0], [-1] * n)
while stack:
	u = stack.pop()
	for v in g[u]:
		parent[v] = u
		if len(g[v]) > 1:
			g[v].remove(u)
			stack.append(v)
color = [0] * n
for (u, v) in white:
	color[u if parent[u] == v else v] = 1
color[0] = 2
for (u, c) in enumerate(color):
	if c == 1:
		u = parent[u]
		while color[u] != 2:
			(color[u], u) = (2, parent[u])
res = [i for (i, c) in enumerate(color, 1) if c == 1]
print(len(res))
print(' '.join([str(x) for x in res]))
